import 'dart:async';
import 'dart:io';
import 'dart:typed_data';
import 'package:camera/camera.dart';
import 'package:flutter/material.dart';
import 'package:image/image.dart' as img; // Import the image package with an alias
import 'package:path_provider/path_provider.dart';

Future<File?> convertCameraImageToPng(CameraImage cameraImage) async {
  try {
    img.Image? image;

    if (cameraImage.format.group == ImageFormatGroup.yuv420) {
      // YUV to RGB conversion
      image = _convertYUV420(cameraImage);

    } else if (cameraImage.format.group == ImageFormatGroup.bgra8888) {
      // BGRA to RGB conversion
      image = _convertBGRA8888(cameraImage);
    } else {
      print("Unsupported image format: ${cameraImage.format.group}");
      return null;
    }

    if (image == null) {
      print("Failed to decode camera image.");
      return null;
    }

    // Encode the image to PNG
    List<int> pngBytes = img.encodePng(image);

    // Get temporary directory
    final appDir = await getTemporaryDirectory();
    final filePath = '${appDir.path}/${DateTime.now().millisecondsSinceEpoch}.png';

    // Save the image to file
    File file = File(filePath);
    await file.writeAsBytes(pngBytes);

    print('Image saved to: ${file.path}');
    return file;

  } catch (e) {
    print("Error converting camera image to PNG: $e");
    return null;
  }
}

img.Image? _convertYUV420(CameraImage image) {
  try {
    final int width = image.width;
    final int height = image.height;
    final int uvRowStride = image.planes[1].bytesPerRow;
    final int uvPixelStride = image.planes[1].bytesPerPixel!;

    // imgLib -> Image conversion
    var imgImage = img.Image(width: width, height: height);

    for (int w = 0; w < width; w++) {
      for (int h = 0; h < height; h++) {
        final int uvIndex = uvPixelStride * (w ~/ 2) + uvRowStride * (h ~/ 2);
        final int index = h * width + w;

        // YUV to RGB conversion
        final y = image.planes[0].bytes[index];
        final u = image.planes[1].bytes[uvIndex];
        final v = image.planes[2].bytes[uvIndex];

        // Convert to RGB using specific formula for YUV420
        int r = (y + 1.13983 * (v - 128)).round().clamp(0, 255);
        int g = (y - 0.39465 * (u - 128) - 0.58060 * (v - 128)).round().clamp(0, 255);
        int b = (y + 2.03211 * (u - 128)).round().clamp(0, 255);

        imgImage.setPixelRgba(w, h, r, g, b, 255);
      }
    }
    return imgImage;

  } catch (e) {
    print("ERROR: YUV conversion failed: $e");
    return null;
  }
}

img.Image? _convertBGRA8888(CameraImage image) {
  try {
    final int width = image.width;
    final int height = image.height;

    var imgImage = img.Image(width: width, height: height);
    for (int x = 0; x < width; x++) {
      for (int y = 0; y < height; y++) {
        int index = y * width + x;
        int bgraIndex = index * 4; // Each pixel is 4 bytes (BGRA)

        int b = image.planes[0].bytes[bgraIndex];       // Blue
        int g = image.planes[0].bytes[bgraIndex + 1];   // Green
        int r = image.planes[0].bytes[bgraIndex + 2];   // Red
        int a = image.planes[0].bytes[bgraIndex + 3];   // Alpha

        imgImage.setPixelRgba(x, y, r, g, b, a);
      }
    }
    return imgImage;

  } catch (e) {
    print('ERROR converting BGRA8888: $e');
    return null;
  }
}


